export function hexToRgba(hex) {
    if (hex.startsWith('#')) {
        return `rgba(${parseInt(`0x${hex.slice(1, 3)}`)},${parseInt(`0x${hex.slice(3, 5)}`)},${parseInt(`0x${hex.slice(5, 7)}`)},0.2)`;
    }
    if (hex.startsWith('rgb(')) {
        return hex.replace('rgb(', 'rgba(').replace(/\)$/, ', 0.2)');
    }
    return hex;
}
